// Safe for any n: the recursive call is a tail call.
static long sum(long n, long acc) {
    if (n == 0) return acc;
    return sum(n - 1, acc + n);
}

static int depth(File dir) {
    int best = 0;
    for (File child : dir.listFiles()) {
        if (child.isDirectory()) best = Math.max(best, depth(child));
    }
    return best + 1;
}
